// Next.js roadmap questions (120): 15 levels × 8, easiest → hardest. Focused on
// the modern App Router (Next.js 13+). Built directly. See lib/roadmap.ts.

import type { Seed } from './roadmap-build';

export const nextSeeds: Seed[] = [
  // ── Level 1 — Next.js Basics ───────────────────────────────────────────
  { q: 'What is Next.js?', opts: ['A build tool that bundles any JavaScript project', 'A React framework for production web apps', 'A React alternative with its own component model', 'A hosting platform for JavaScript applications'], a: 1, e: 'Next.js is built on React: you still write React components, and the framework adds routing, rendering strategies, and build tooling on top. It is not a general-purpose bundler you point at any project, and it is not a React alternative. Vercel hosts Next.js apps, but the framework is open source and runs anywhere Node.js does.', intro: 'Next.js does not replace React. Decide which layer sits above the component library.', tags: ['Next.js', 'Basics'] },
  { q: 'Next.js is built on top of which library?', opts: ['Vue', 'Angular', 'React', 'Svelte'], a: 2, e: 'Next.js is a framework built around React.', tags: ['Next.js', 'Basics'] },
  { q: 'Which capability does Next.js add around React rather than React providing it by itself?', opts: ['Component state through hooks', 'Declarative elements through JSX', 'File-based routing and server rendering conventions', 'Browser event handling through props'], a: 2, e: 'React gives you the component model: state through hooks, JSX elements and event handlers all work in a plain React app with no framework. Next.js adds the application layer on top of that: file-based routes, nested layouts, server rendering, data-loading conventions and build tooling. That is why the other three options are React features rather than things the framework contributes.', intro: 'Ask which of these you already get from React itself, with no framework around it.', tags: ['Next.js', 'Basics'] },
  { q: 'Which routing system does a new Next.js project use by default?', opts: ['The Pages Router', 'The App Router', 'The Hash Router', 'React Router'], a: 1, e: 'The App Router (the `app/` directory) is what `create-next-app` scaffolds and what the current docs are written against. The Pages Router (`pages/`) still works and is maintained for existing apps, which makes it a migration target rather than the default. Hash Router and React Router are client-side React libraries, not Next.js routing systems.', intro: 'Two of these four ship with Next.js and two are separate React libraries. Between the two, ask which one a fresh scaffold sets up.', tags: ['Next.js', 'Basics'] },
  { q: 'Which file defines a route’s page UI in the App Router?', opts: ['index.tsx', 'route.tsx', 'page.tsx', 'app.tsx'], a: 2, e: 'A `page.tsx` (or `.js`/`.jsx`) file makes its folder a publicly accessible route, and its default export renders the UI. `route.ts` is the other public file convention, but it defines an HTTP endpoint returning a `Response`, not UI. `index.tsx` is the Pages Router habit (`pages/index.tsx`); `app.tsx` is not a convention in either router, and neither name means anything inside `app/`.', intro: 'One special file makes its folder publicly reachable and renders UI; another returns a `Response` instead. Pick the first.', tags: ['Next.js', 'Basics'] },
  { q: 'By default, components in the App Router are:', opts: ['Client Components, unless you opt into the server', 'Server Components, unless you opt into the client', 'Client Components in development, Server Components in production', 'Server Components only when the component is declared `async`'], a: 1, e: 'Every component under `app/` renders on the server unless its module carries `"use client"`, so the client bundle stays small by default. The opt-in runs one way only: you add a directive to reach the client, never to reach the server. The default does not change between development and production, and it does not depend on whether the component is `async`.', intro: 'Which environment does the App Router pick when a file carries no directive at all?', tags: ['Next.js', 'Basics'] },
  { q: 'Next.js provides built-in:', opts: ['manual route configuration', 'file-based routing', 'no routing', 'client-only routing'], a: 1, e: 'Routes are defined by the file/folder structure — no central route config.', tags: ['Next.js', 'Basics'] },
  { q: 'How do you scaffold a new Next.js app?', opts: ['`npm install create-next-app`', '`npx create-next-app@latest`', '`npx next init`', '`npm create vite@latest`'], a: 1, e: '`npx create-next-app@latest` downloads and runs the generator once, scaffolds the project and installs dependencies; the `@latest` tag matters because the generator is versioned separately from your app. There is no `next init`: the `next` CLI has `dev`, `build` and `start`, and it needs an existing project. `npm create vite@latest` scaffolds a Vite project, and installing the generator as a dependency is not how it is meant to run.', intro: 'Project generators run through a one-off package runner, not through a subcommand of the framework\'s own CLI.', tags: ['Next.js', 'Basics'] },

  // ── Level 2 — Routing (App Router) ─────────────────────────────────────
  { q: 'In the App Router, routes are defined by:', opts: ['a `routes.js` file at the project root', 'folders inside the `app/` directory', 'a route config object passed to the router', 'the components you import into `app/layout.tsx`'], a: 1, e: 'Each folder under `app/` is a route segment, and the segment becomes publicly reachable once it contains a `page.tsx` or `route.ts`. There is no central route table and no config object to register, so renaming a folder changes the URL. Importing a component into a layout renders it everywhere; it does not create a route.', intro: 'Think about what you would add to create a new URL in an App Router project, and whether any other file has to be updated to match.', tags: ['Next.js', 'Routing'] },
  { q: 'A folder `app/blog/` with a `page.tsx` maps to which URL?', opts: ['/app/blog', '/blog', '/blog/page', '/blog.html'], a: 1, e: '`app/` is the router\'s root, not a URL segment, so only the folders under it form the path: `app/blog` serves `/blog`. The special file name never appears either, because `page.tsx` marks the folder as a route rather than adding a `/page` segment. The App Router serves clean paths, so no `.html` extension is added.', intro: 'Decide whether `app` itself is part of the URL before you look at the rest of the path.', tags: ['Next.js', 'Routing'] },
  { q: 'Where is the root layout defined?', opts: ['app/root.tsx', 'app/layout.tsx', 'app/_app.tsx', 'layout.config.js'], a: 1, e: '`app/layout.tsx` is the root layout: nothing sits above it, it wraps every route, and it must render `<html>` and `<body>`. `_app.tsx` is the Pages Router\'s equivalent and is ignored inside `app/`; `root.tsx` and `layout.config.js` are not conventions at all. Route groups let a project have more than one root layout, but each of those is still a `layout.tsx`.', intro: 'Ask which of these names is an actual App Router file convention rather than a Pages Router habit.', tags: ['Next.js', 'Routing'] },
  { q: 'What does a `loading.tsx` file provide?', opts: ['an error page', 'an instant loading UI for that segment', 'a 404 page', 'a layout'], a: 1, e: '`loading.tsx` wraps the segment in a React `<Suspense>` boundary automatically, so the fallback appears immediately while the page\'s data resolves and the content streams in afterward. The neighboring conventions cover the other states: `error.tsx` is the error boundary, `not-found.tsx` renders the 404 UI, and `layout.tsx` is shared wrapper UI that persists across navigation.', intro: 'Four special files sit side by side in one folder. Match this one to the React boundary it installs.', tags: ['Next.js', 'Routing'] },
  { q: 'What does an `error.tsx` file provide?', opts: ['a loading UI', 'an error boundary UI for the segment', 'a redirect', 'a layout'], a: 1, e: '`error.tsx` becomes a React error boundary around its route segment, so a throw while rendering below it shows this UI instead of taking down the whole page, and the component receives a `retry()` function that re-fetches and re-renders the segment (Next.js 16; earlier releases passed `reset`). `loading.tsx` covers the pending state, not the failure state, and `not-found.tsx` covers the missing-resource case. Redirects come from calling `redirect()`, not from a file convention.', intro: 'Ask which React boundary this file installs, and what it catches that a Suspense fallback does not.', tags: ['Next.js', 'Routing'] },
  { q: 'A folder named `(marketing)` with parentheses is:', opts: ['a dynamic segment that captures that part of the URL', 'a group that organizes routes without changing the URL', 'a private folder that is excluded from routing', 'a layout applied to every route beneath it'], a: 1, e: 'Parentheses mark a route group: the folder organizes files and can carry its own `layout.tsx`, but its name is dropped from the URL, so `app/(marketing)/about/page.tsx` serves `/about`. Square brackets `[id]` would make the segment dynamic instead. An underscore prefix `_folder` opts the folder out of routing entirely rather than just hiding its name from the path.', intro: 'Brackets, parentheses and underscores each mark a folder differently. Ask what parentheses do to the URL.', tags: ['Next.js', 'Routing'] },
  { q: 'What does a `not-found.tsx` render?', opts: ['the fallback shown while the segment loads', 'the UI for a missing resource (the 404 case)', 'the fallback shown when rendering throws', 'the shared wrapper around the segment'], a: 1, e: '`not-found.tsx` renders when you call `notFound()` in a Server Component or when no route matches under that segment. `loading.tsx` handles the pending state and `error.tsx` the thrown-error state, so neither covers a resource that simply does not exist, and `layout.tsx` is the persistent wrapper. In Next.js 16 the status code depends on the response: 404 for a non-streamed response, and 200 once streaming has started.', intro: 'One of these files is reached by calling a function from your own code. Recall which function that is.', tags: ['Next.js', 'Routing'] },
  { q: 'A project has `app/layout.tsx`, `app/dashboard/layout.tsx` and `app/dashboard/settings/page.tsx`. What renders at `/dashboard/settings`?', opts: ['the page alone; layouts wrap only the page in their own folder', 'the root layout, then the dashboard layout, then the page', 'the dashboard layout and the page; the root layout is skipped', 'the root layout and the page; the dashboard layout is skipped'], a: 1, e: 'Folder nesting maps to both URL nesting and layout nesting: every layout on the path from `app/` down to the page wraps everything below it, so the root layout wraps the dashboard layout, which wraps the page. A deeper layout adds to that chain rather than replacing what is above it, and none of them is skipped. That is what lets a section keep its own chrome inside the site-wide shell.', intro: 'Decide whether a layout deeper in the tree adds to the layouts above it or takes their place.', tags: ['Next.js', 'Routing'] },

  // ── Level 3 — Pages & Layouts ──────────────────────────────────────────
  { q: 'You navigate from `/dashboard/a` to `/dashboard/b`, both under `app/dashboard/layout.tsx`. What happens to state held in a Client Component inside that layout?', opts: ['It resets, because the layout remounts for each page', 'It is preserved, because the layout does not remount', 'It is preserved only when both pages share a template', 'It resets, because navigation reloads the document'], a: 1, e: 'Layouts wrap their segment and stay mounted while you navigate within it, so a Client Component in the layout keeps its state and its effects do not re-run. A `<Link>` navigation is client-side and does not reload the document, so nothing is torn down. If you want a reset instead, that is what `template.tsx` is for: Next.js gives it a fresh key whenever its own segment changes.', intro: 'Decide whether Next.js remounts the shared layout on navigation or reuses the instance already on screen.', tags: ['Next.js', 'Layouts'] },
  { q: 'A new `app/layout.tsx` returns only `<main>{children}</main>`, and Next.js reports that required root tags are missing. Which structure fixes it?', opts: ['`<head><main>{children}</main></head>`', '`<html><body><main>{children}</main></body></html>`', '`<body><main>{children}</main></body>`', '`<html><main>{children}</main></html>`'], a: 1, e: 'The root layout owns the document, so it must render both `<html>` and `<body>`; Next.js reports an error when either is missing. Wrapping the children in `<main>` alone, or in `<body>` without `<html>`, still leaves the document incomplete. `<head>` is not written by hand here at all: title and meta tags come from the Metadata API, and nested layouts must not repeat the document-level tags.', intro: 'The error is about the document shell, not about `<main>`. Recall what the root layout must render that no nested layout may repeat.', tags: ['Next.js', 'Layouts'] },
  { q: 'A layout receives the page to render via which prop?', opts: ['props.page', 'the children prop', 'a slot', 'useRoute()'], a: 1, e: 'Layouts are plain React components, so the nested layout or page arrives as the standard `children` prop and the layout chooses where to render it. There is no `props.page` and no `useRoute()` hook. Named slots do exist, but only for parallel routes, and they arrive as their own props such as `props.analytics` alongside `children`.', intro: 'A layout is an ordinary React component; the mechanism here is not specific to Next.js.', tags: ['Next.js', 'Layouts'] },
  { q: 'How does a `template.tsx` differ from a layout?', opts: ['it persists state', 'it re-mounts (fresh state) on each navigation', 'it’s for errors', 'it’s server-only'], a: 1, e: 'Next.js gives a template a new key when its segment changes, so React unmounts the old instance and mounts a new one: Client Component state resets and effects re-synchronize. A layout keeps its instance and therefore its state. Both are Server Components by default, so \'server-only\' is not the difference, and neither has anything to do with error handling.', intro: 'One of the two gets a fresh React key on navigation. Ask what a changed key does to component state.', tags: ['Next.js', 'Layouts'] },
  { q: 'Can routes have multiple layouts?', opts: ['only one allowed', 'yes — each folder can have its own, and they nest', 'global only', 'client-only'], a: 1, e: 'Layouts nest: each segment can add its own layout around the deeper ones.', tags: ['Next.js', 'Layouts'] },
  { q: 'What must `app/blog/page.tsx` export for `/blog` to render?', opts: ['a named export called `Page`', 'a default-exported React component', 'an object describing the route\'s config', 'a `render()` function that returns JSX'], a: 1, e: 'Next.js imports `page.tsx` by file convention and renders whatever the module exports by default, so the route UI must be the default export; a named export is not picked up no matter what it is called. Route configuration happens through separate named exports such as `metadata` or `generateStaticParams`, not by returning a config object. There is no `render()` method: the default export is a plain function component.', intro: 'This file can also export `metadata` and `generateStaticParams`. Ask what makes the UI export different from those.', tags: ['Next.js', 'Layouts'] },
  { q: 'Layouts in the App Router are by default:', opts: ['Client Components', 'Server Components', 'static files', 'client-only'], a: 1, e: 'Like pages, layouts are Server Components unless marked "use client".', tags: ['Next.js', 'Layouts'] },
  { q: 'A header is placed in the root `app/layout.tsx`. Where does it render?', opts: ['on the home page only', 'on every route the layout wraps', 'on every route except dynamic ones', 'only on routes that have no layout of their own'], a: 1, e: 'The root layout wraps every route beneath it, so shared chrome placed there renders on all of them and stays mounted as you navigate. A nested layout adds UI inside the root layout rather than replacing it, so having its own layout does not exempt a route, and a dynamic segment is an ordinary route in this respect. Only a separate root layout, created with route groups, would opt a section out.', intro: 'A route deeper in the tree can have its own `layout.tsx`. Decide whether that replaces the root one or nests inside it.', tags: ['Next.js', 'Layouts'] },

  // ── Level 4 — Navigation & Links ───────────────────────────────────────
  { q: 'A nav uses `<a href="/about">` instead of `<Link href="/about">`. What changes?', opts: ['Nothing; Next.js upgrades every `<a>` into a client transition', 'The browser reloads the document instead of transitioning on the client', 'The route still transitions on the client, but without prefetching', 'The link stops working, because `app/` routes require `<Link>`'], a: 1, e: '`<Link>` renders a real `<a>` but intercepts the click and performs a client-side transition, fetching only the segments that changed and keeping shared layouts mounted; in production it also prefetches the route once the link enters the viewport. A plain `<a>` hands the click to the browser, which reloads the document and rebuilds the whole tree, losing client state. The route itself still resolves, so the link works, it is just slower.', intro: '`<Link>` renders an `<a>`, so ask what the router adds on top of the browser\'s own navigation.', tags: ['Next.js', 'Navigation'] },
  { q: 'What does `<Link href="/about">` do?', opts: ['a full page reload', 'client-side navigation without a full reload', 'opens a new tab', 'submits a form'], a: 1, e: '<Link> navigates on the client, fetching only what changed.', tags: ['Next.js', 'Navigation'] },
  { q: 'To navigate programmatically in a Client Component, use:', opts: ['useRouter from next/router', 'useRouter from next/navigation', 'useNavigate', 'window.location only'], a: 1, e: 'In the App Router, `useRouter` comes from `next/navigation`; the `next/router` version belongs to the Pages Router and fails when used inside `app/`. It works only in a Client Component, so the module needs `"use client"` at the top. `useNavigate` is React Router\'s hook, and `window.location` would trigger a full document reload instead of a client-side transition.', intro: 'Both import paths exist in the package. Recall which one belongs to the router you are actually using.', tags: ['Next.js', 'Navigation'] },
  { q: 'What does `router.push("/x")` do?', opts: ['navigates to /x and replaces the current history entry', 'navigates to /x and adds a new history entry', 'navigates to /x and clears the history stack', 'reloads the document at /x'], a: 1, e: '`router.push` performs a client-side navigation and pushes a new entry onto the browser history stack, so Back returns to the page you left. `router.replace` performs the same navigation without adding an entry, which is what you want after a login redirect so Back does not return to the form. Neither one reloads the document, and nothing in the router API clears history.', intro: '`push` and `replace` both navigate. Ask what the Back button will do afterward.', tags: ['Next.js', 'Navigation'] },
  { q: 'What does `usePathname()` return?', opts: ['the query string', 'the current URL path', 'the host', 'route params'], a: 1, e: '`usePathname` returns just the path portion of the current URL as a string, for example `"/blog/post"`, with no origin and no query string. It is a Client Component hook, and the usual use is marking the active link in a nav that lives in a layout. The query string comes from `useSearchParams`, and dynamic segment values come from `useParams` or the `params` prop.', intro: 'You want to highlight the active link in a nav. Ask which piece of the URL that comparison needs.', tags: ['Next.js', 'Navigation'] },
  { q: 'What does `useSearchParams()` read?', opts: ['route params', 'the URL query-string parameters', 'the pathname', 'headers'], a: 1, e: '`useSearchParams` returns a read-only `URLSearchParams` view of everything after `?`, so `searchParams.get("q")` reads `?q=`. It is a Client Component hook and is not supported in Server Components; a Server Component page reads the `searchParams` prop instead. Dynamic path segments are `params`, not search params, and request headers need the `headers()` function.', intro: 'A filter UI changes what the page shows without changing the route. Ask which part of the URL carries those values.', tags: ['Next.js', 'Navigation'] },
  { q: 'By default in production, when does <Link> prefetch the linked route?', opts: ['Never — prefetching must be enabled per link', 'When the link enters the viewport', 'Only after the user clicks it', 'Only when router.prefetch() is called manually'], a: 1, e: 'In production, Next.js prefetches a `<Link>`\'s route and its data when the link scrolls into the viewport, so the transition is usually already loaded by the time the user clicks. Prefetching is on by default (`prefetch` is `"auto"`), not something you enable per link, and `router.prefetch()` exists only for cases `<Link>` does not cover. Prefetching is disabled in development, which is why navigation feels slower there.', intro: 'Prefetching costs a request per link, so ask at what moment the router has enough reason to spend one.', tags: ['Next.js', 'Navigation'] },
  { q: 'During a Server Component render, what does `redirect("/login")` from `next/navigation` do?', opts: ['renders a link to /login that the user has to click', 'stops rendering that segment and sends the user to /login', 'queues a redirect that runs after the page is sent', 'sets a `Location` header without changing the status code'], a: 1, e: '`redirect()` throws a `NEXT_REDIRECT` signal that Next.js catches: rendering of that segment stops immediately, so code after the call never runs, and the response becomes a 307 redirect (303 for a progressive-enhancement Server Action form post). Because it throws, call it outside `try/catch` or your own handler will swallow it. It renders nothing and does not defer the redirect until after the response.', intro: 'Ask what happens to the rest of the component\'s code after the call, and to the response.', tags: ['Next.js', 'Navigation'] },

  // ── Level 5 — Server & Client Components ───────────────────────────────
  { q: 'By default, a component in `app/` is a:', opts: ['Client Component', 'Server Component', 'static page', 'hook'], a: 1, e: 'App Router components render on the server unless opted into the client.', tags: ['Next.js', 'Components'] },
  { q: 'A component needs `useState` and a click handler. How should you create the client boundary?', opts: ['Put `"use server"` above the component', 'Put `"use client"` at the top of the module', 'Add `{ client: true }` to the default export', 'Rename the file to `component.client.tsx`'], a: 1, e: '`"use client"` at the very top of the module, above the imports, marks it as an entry point into the client module graph, so the component may use state, effects, event handlers and browser APIs. `"use server"` does the opposite: it marks Server Functions that client code can call. There is no `{ client: true }` export flag and no `.client.tsx` filename convention in the App Router.', intro: 'One directive moves a module into the client bundle. Recall which one, and where in the file it has to sit.', tags: ['Next.js', 'Components'] },
  { q: 'Which of these can a Server Component do that a Client Component cannot?', opts: ['hold state across renders with `useState`', 'read a database or secret directly during render', 'attach an `onClick` handler to a button', 'read `window.localStorage` while rendering'], a: 1, e: 'A Server Component runs only on the server and its code never enters the client bundle, so it can query a database or use an API key directly in the render and pass only the result down. State, event handlers and browser APIs all need code running in the browser, so they belong to Client Components. That asymmetry is the point of the split: it keeps credentials and data-access code off the wire.', intro: 'Sort the four by what each one needs at the moment of rendering: a browser, or a server.', tags: ['Next.js', 'Components'] },
  { q: 'Hooks like `useState`/`useEffect` can be used:', opts: ['in any component under `app/`', 'only in modules marked `"use client"`', 'only in components that are not `async`', 'only in components below the root layout'], a: 1, e: '`useState` and `useEffect` need React running in the browser, so they work only inside a module marked `"use client"`; calling them from a Server Component is a build error. Being synchronous does not help, because a plain Server Component still has no place to keep state between renders. Position in the tree is irrelevant: what matters is which side of the `"use client"` boundary the module sits on.', intro: 'Two of these options talk about where a component sits in the tree. Ask whether position has anything to do with it.', tags: ['Next.js', 'Components'] },
  { q: 'A Server Component renders `<button onClick={() => setOpen(true)}>`. What happens?', opts: ['It works; Next.js hydrates the handler on the client', 'It fails; handlers have to live in a Client Component', 'It works, but the handler runs on the server', 'It works only when the page is dynamically rendered'], a: 1, e: 'A Server Component\'s output is serialized into the RSC payload, and a function cannot cross that boundary, so passing `onClick` from a Server Component is an error rather than something Next.js hydrates for you. The same rule covers `window`, `localStorage` and other browser APIs. The fix is to move the interactive part into a module marked `"use client"` and render it from the Server Component.', intro: 'A Server Component\'s output crosses to the browser as data. Ask what happens to a function when it has to travel that way.', tags: ['Next.js', 'Components'] },
  { q: 'Which direction of composition does the App Router allow?', opts: ['A Client Component may import and render a Server Component', 'A Server Component may import and render a Client Component', 'Neither direction; the two module graphs stay separate', 'Either direction, because the boundary is per component'], a: 1, e: 'A Server Component can import a Client Component and render it, because the `"use client"` module is where the client bundle begins. The reverse import does not work: everything a Client Component imports joins the client graph, so a Server Component pulled in that way would be turned into client code. You can still nest server-rendered UI inside a Client Component by passing it through `children`, since props carry rendered output rather than imports.', intro: 'The boundary belongs to modules, not to components. Ask which side may pull the other into its graph.', tags: ['Next.js', 'Components'] },
  { q: 'A key benefit of Server Components is:', opts: ['more client JavaScript', 'less JavaScript sent to the browser', 'no server needed', 'automatic global state'], a: 1, e: 'Rendering on the server keeps the client bundle smaller.', tags: ['Next.js', 'Components'] },
  { q: 'What is the scope of `"use client"` at the top of a module?', opts: ['It switches every route in the application to client rendering', 'It creates a client boundary for that module and the modules it imports', 'It changes only the first component declared in the file', 'It makes the module run once in both the Node and Edge runtimes'], a: 1, e: 'The directive marks an entry point into the client module graph: that module and everything it imports are bundled for the browser, which is why you put it on the small interactive leaf rather than near the root. It applies to the whole module rather than to one declaration in it, it does not convert the application, and it has nothing to do with the Node or Edge runtime. Server Components passed in as `children` stay on the server, because props carry rendered output rather than imports.', intro: 'One file in a large app carries this directive. Ask whether that tells you anything about the app\'s other routes.', tags: ['Next.js', 'Components'] },

  // ── Level 6 — Data Fetching ────────────────────────────────────────────
  { q: 'In a Server Component, how do you fetch data?', opts: ['`useEffect` with `fetch`, then store the result in state', '`await fetch(...)` directly in the async component', 'export `getStaticProps` from the page file', 'export `getServerSideProps` from the page file'], a: 1, e: 'A Server Component may be declared `async` and `await` a promise in its body, so you call `fetch` (or a database client) directly and render the result, with no wrapper function and no client round trip. `useEffect` runs only in the browser, after the HTML is already there, which reintroduces the loading spinner the server render was meant to avoid. `getStaticProps` and `getServerSideProps` are Pages Router exports and are ignored inside `app/`.', intro: 'A Server Component\'s body runs on the server before any HTML is sent. Ask what that removes the need for.', tags: ['Next.js', 'Data'] },
  { q: 'A Server Component can be:', opts: ['never async', 'an async function', 'only with hooks', 'client-only'], a: 1, e: 'Server Components may be declared `async` and await data.', tags: ['Next.js', 'Data'] },
  { q: 'A shared catalogue changes only when the application is redeployed. Which `fetch` option explicitly allows Next.js to reuse its cached result?', opts: ['`{ cache: "no-store" }`', '`{ cache: "force-cache" }`', '`{ next: { revalidate: 0 } }`', '`{ cache: "reload" }`'], a: 1, e: 'Since Next.js 15 a server `fetch` does not use the framework\'s data cache unless you ask for it, and `cache: "force-cache"` is that request: a matching cached response is reused instead of going to the origin. `no-store` and `next: { revalidate: 0 }` both prevent caching, which is the opposite of what a redeploy-stable catalog needs. `cache: "reload"` is a browser HTTP-cache value; Next.js documents only `force-cache` and `no-store` for its server cache.', intro: 'A plain `fetch` on the server is not cached by default. Ask which value opts this one in.', tags: ['Next.js', 'Data'] },
  { q: 'An account page must read fresh private data on every request, including on a route Next.js would otherwise prerender. Which `fetch` option guarantees that?', opts: ['`{ cache: "force-cache" }`', '`{ cache: "no-store" }`', '`{ next: { revalidate: 3600 } }`', '`{ cache: "only-if-cached" }`'], a: 1, e: '`cache: "no-store"` fetches from the origin on every request and stores nothing, so no prerender and no cached entry can serve one user\'s private data to another. `force-cache` does the opposite, and `next: { revalidate: 3600 }` still serves a stored response for up to an hour, which is exactly the stale-private-data bug. `only-if-cached` is a browser HTTP-cache value; Next.js documents only `force-cache` and `no-store` for its server cache.', intro: 'Only two of these four are Next.js server-cache values. Decide which two, then which of them fits \'on every request\'.', tags: ['Next.js', 'Data'] },
  { q: 'To revalidate fetched data every 60 seconds:', opts: ['cache: 60', '{ next: { revalidate: 60 } }', 'revalidate(60)', 'setInterval'], a: 1, e: 'Next.js extends the standard `fetch` options with a `next` object, and `next: { revalidate: 60 }` gives the cached response a lifetime of at most 60 seconds; after that the next request triggers a background refresh, which is ISR at the level of a single request. `cache` accepts only `"force-cache"` or `"no-store"`, so a number there is not a valid value. A client-side `setInterval` would not touch the server cache at all.', intro: 'Next.js adds its own key to the `fetch` options object. Recall which key holds the lifetime.', tags: ['Next.js', 'Data'] },
  { q: 'In the old Pages Router, which function fetched data at build time for static generation (SSG)?', opts: ['getServerSideProps', 'getStaticProps', 'getInitialProps', 'getStaticPaths'], a: 1, e: '`getStaticProps` runs during `next build` and its result is baked into the prerendered page, which is what makes it the static-generation function. `getServerSideProps` runs on the server for every request, `getInitialProps` is the legacy API that predates both, and `getStaticPaths` only lists which dynamic paths to prebuild, leaving the data to `getStaticProps`. None of these exist in the App Router: the equivalent is fetching inside a Server Component, with `generateStaticParams` supplying the paths.', intro: 'Sort the four by when they run, then pick the one that runs before any request exists.', tags: ['Next.js', 'Data'] },
  { q: 'In the legacy Pages Router, when does `getServerSideProps` run?', opts: ['once during `next build`, like `getStaticProps`', 'on the server, for every incoming request', 'in the browser, just before the page hydrates', 'on the server, then again in the browser on navigation'], a: 1, e: '`getServerSideProps` runs on the server for each incoming request and its return value is passed to the page as props, which is what makes the page server-rendered rather than static, and what makes it uncacheable at the CDN. It never runs in the browser: the code is stripped from the client bundle, which is why you can query a database inside it. `getStaticProps` is the build-time counterpart, and in the App Router neither exists, because you fetch inside a Server Component instead.', intro: 'The name says where it runs. Decide how often, and what that costs on a busy page.', tags: ['Next.js', 'Data'] },
  { q: 'In the App Router, request-time data is fetched:', opts: ['with getServerSideProps', 'directly inside Server Components (no special function)', 'only on the client', 'via Redux'], a: 1, e: 'You just fetch in the Server Component; caching options control freshness.', tags: ['Next.js', 'Data'] },

  // ── Level 7 — Dynamic Routes ───────────────────────────────────────────
  { q: 'How do you name a dynamic route segment folder?', opts: ['{id}', ':id', '[id]', '(id)'], a: 2, e: 'Square brackets mark a dynamic segment, so `app/blog/[slug]/page.tsx` matches `/blog/anything` and hands the captured value to the page through `params`. `:id` is the Express and React Router style and `{id}` comes from other frameworks; neither means anything to a file-system router. Parentheses are not a typo variant here: `(id)` is a route group, which is dropped from the URL entirely.', intro: 'Each of these bracket styles belongs to some router. Recall which one Next.js reads out of a folder name.', tags: ['Next.js', 'Dynamic'] },
  { q: 'In `app/blog/[slug]/page.tsx` on Next.js 16, how does the page read `slug`?', opts: ['`props.query.slug`, as in the Pages Router', '`const { slug } = await params`', '`params.slug`, read straight off the prop', '`useSearchParams().get("slug")`'], a: 1, e: 'Since Next.js 15 the `params` prop is a Promise, so a Server Component page awaits it: `const { slug } = await params`. Reading `params.slug` straight off the prop is the Next.js 14 form; version 15 kept it working as temporary compatibility and Next.js 16 removed synchronous access entirely. A Client Component page unwraps the same Promise with React\'s `use(params)`, or calls `useParams()` deeper in the tree. `props.query` is the Pages Router shape, and `useSearchParams` reads `?query=`, not path segments.', intro: 'Since Next.js 15 the prop arrives before its value does. Ask what shape that makes it.', tags: ['Next.js', 'Dynamic'] },
  { q: 'A catch-all route segment is written as:', opts: ['[slug]', '[...slug]', '[[slug]]', '[*slug]'], a: 1, e: '`[...slug]` borrows the rest syntax: it matches one or more remaining segments, and the captured value is an array, so `/shop/a/b` gives `slug` as `[\'a\',\'b\']`, not a string. `[slug]` matches exactly one segment. The optional variant keeps the dots inside doubled brackets, `[[...slug]]`; `[[slug]]` on its own is not a convention, and neither is `[*slug]`.', intro: 'This is the same folder-name trick as a single dynamic segment, with one more piece of syntax inside the brackets.', tags: ['Next.js', 'Dynamic'] },
  { q: '`app/shop/[...slug]/page.tsx` returns a 404 for `/shop` itself. Which folder name fixes that?', opts: ['`[slug]`', '`[[...slug]]`', '`[...slug?]`', '`(shop)`'], a: 1, e: '`[[...slug]]` is the optional catch-all: it matches `/shop` with no further segments, where `slug` is `undefined`, as well as `/shop/a` and `/shop/a/b`. The single-bracket `[...slug]` requires at least one segment, which is why `/shop` fell through to a 404. `[...slug?]` is not a convention, and `(shop)` is a route group: its name is dropped from the URL and it captures nothing.', intro: 'The route has to match when the segment list is empty. Ask which form makes the parameter optional.', tags: ['Next.js', 'Dynamic'] },
  { q: 'What does `generateStaticParams()` do?', opts: ['fetches the data each prerendered page will display', 'returns the params whose pages are prerendered at build', 'validates params and 404s the ones it does not list', 'declares which params force dynamic rendering instead'], a: 1, e: '`generateStaticParams` returns a list of param objects and Next.js prerenders one page per entry at build time; it is the App Router\'s replacement for the Pages Router\'s `getStaticPaths`. It supplies the params, not the content: the page still fetches its own data for each one. Params it does not list are not rejected by default either, they are rendered on demand at request time unless you also set `dynamicParams = false`.', intro: 'Compare it with the page\'s own data fetching. Ask which of those two jobs this function is doing.', tags: ['Next.js', 'Dynamic'] },
  { q: 'A request hits `/product/42` on `app/product/[id]/page.tsx`. After `const { id } = await params`, what is `id`?', opts: ['`42` (a number)', '`"42"` (a string)', '`undefined` until the page hydrates', '`["42"]` (an array)'], a: 1, e: 'Route params are parsed out of the URL as text, so `id` is the string `"42"`; Next.js never coerces a numeric-looking segment. Convert explicitly with `Number(id)` before arithmetic or a strict comparison against a numeric id, or the check silently fails. Only a catch-all segment such as `[...id]` produces an array, and because the page awaited `params`, the value is resolved by the time it renders.', intro: 'You are about to compare `id` with a numeric database id. Ask what a strict `===` would do with it.', tags: ['Next.js', 'Dynamic'] },
  { q: 'Dynamic params are provided to a page/layout via:', opts: ['the URL string only', 'the `params` prop', 'a global', 'localStorage'], a: 1, e: 'Next.js passes a params object to the segment’s page and layout.', tags: ['Next.js', 'Dynamic'] },
  { q: 'A Server Component page has to read `?q=` from the URL. What does it use?', opts: ['the `params` prop', 'the `searchParams` prop, awaited', '`useSearchParams()` called on the server', '`headers()` to parse the request URL'], a: 1, e: 'A Server Component page receives `searchParams`, and since Next.js 15 it is a Promise: `const { q } = await searchParams`. `params` carries only dynamic path segments such as `[slug]`, so it never holds `?q=`. `useSearchParams` is a Client Component hook and is documented as unsupported in Server Components, which rules it out here. Reading `searchParams` marks the page as request-time data, so it will not be fully prerendered.', intro: 'Path segments and query strings arrive on different props. Ask which one the `?` belongs to.', tags: ['Next.js', 'Dynamic'] },

  // ── Level 8 — Rendering Strategies ─────────────────────────────────────
  { q: 'A product page is rendered on the server for each request because it must contain request-time data. Which mode fits?', opts: ['SSG', 'SSR', 'CSR', 'ISR'], a: 1, e: 'Server-side rendering builds the HTML on the server for each incoming request, which is what request-time data requires. SSG produces the page once at build, so it cannot contain this request\'s data; ISR serves a stored page and refreshes it on a schedule, so it is stale between refreshes; CSR ships an empty shell and fetches from the browser, losing the server-rendered HTML. In the App Router you get this by reading request-time data such as cookies, headers or `searchParams` in a Server Component.', intro: 'Sort the four by when the HTML is produced, then match that to \'for each request\'.', tags: ['Next.js', 'Rendering'] },
  { q: 'A documentation site is rendered during the build and deployed as ready-to-serve files. Which mode fits?', opts: ['SSR', 'SSG', 'CSR', 'ISR'], a: 1, e: 'Static site generation renders the pages during the build and deploys ready-to-serve files, so requests are answered from disk or a CDN with no rendering work, which fits content that only changes when you redeploy. SSR would re-render for every visitor with nothing to gain, ISR would add a revalidation schedule this content does not need, and CSR would make the browser do the work and hurt indexing. In the App Router this is what you get by default for a route that reads no request-time data.', intro: 'Nothing on this site changes between deploys. Ask which mode does the rendering work only once.', tags: ['Next.js', 'Rendering'] },
  { q: 'A static product page may be regenerated after a revalidation interval without rebuilding the whole site. Which mode fits?', opts: ['SSR', 'ISR', 'CSR', 'SSG only'], a: 1, e: 'Incremental Static Regeneration keeps a prerendered page and regenerates it after a revalidation interval, so a product page can update without a full rebuild and without paying render cost on every request. Plain SSG would stay frozen until the next deploy, and SSR would re-render for every visitor even though the content changes rarely. In the App Router you set this per request with `next: { revalidate }` on a fetch, or per route with the segment\'s revalidate option.', intro: 'Two modes render ahead of time, but only one of them can refresh afterward. Pick that one.', tags: ['Next.js', 'Rendering'] },
  { q: 'A page rendered to static HTML at build time is:', opts: ['SSR', 'SSG', 'CSR', 'ISR'], a: 1, e: 'Building the HTML ahead of time is static generation (SSG).', tags: ['Next.js', 'Rendering'] },
  { q: 'What does Incremental Static Regeneration (ISR) let you do?', opts: ['Rebuild and redeploy the whole site on every content change', 'Refresh individual prerendered pages after deploy without a full rebuild', 'Turn caching off for the route so every request is fresh', 'Move the page\'s rendering out of the server and into the browser'], a: 1, e: 'ISR revalidates a prerendered page on a timer or on demand, so one page can be replaced while the rest keep serving from cache and no rebuild or redeploy is needed. It is not the same as turning caching off: the cached page is still served, and it is still rendered on the server, not in the browser.', intro: 'The name says both \'incremental\' and \'static\'. Check each option against both words.', tags: ['Next.js', 'Rendering'] },
  { q: 'The server sends an HTML shell, then browser JavaScript fetches data and builds the page. Which mode describes the main render?', opts: ['SSR', 'SSG', 'CSR', 'ISR'], a: 2, e: 'The server sends only a shell, so the markup the user reads is produced by the browser: that is client-side rendering. SSR would have sent the finished HTML for that first response, SSG would have produced it at build time, and ISR is SSG plus revalidation.', intro: 'Ask which machine produced the markup the user finally reads, not which one sent the first bytes.', tags: ['Next.js', 'Rendering'] },
  { q: 'In the App Router, what makes a route render per request instead of being prerendered?', opts: ['Nothing: every App Router route is rendered per request anyway', 'Reading request data with `cookies()`, `headers()`, `searchParams` or `draftMode()`', 'Nothing: App Router routes are always prerendered at build time', 'Exporting `getServerSideProps` from the page file'], a: 1, e: 'Request-time APIs such as `cookies()`, `headers()`, `searchParams` and `draftMode()` cannot run during the build, so a component that reads one opts its route into dynamic rendering. A `fetch` left at the default setting does not: since Next.js 15 fetch is uncached by default, and such a request still runs once at build time when no request-time API precedes it. `getServerSideProps` is a Pages Router export and is ignored under `app/`.', intro: 'Only one thing forces work at request time: needing a value that does not exist until the request arrives.', tags: ['Next.js', 'Rendering'] },
  { q: 'What does `export const dynamic = "force-dynamic"` do?', opts: ['Caches the route\'s output permanently', 'Renders the route on the server for every request', 'Disables the route in production builds', 'Redirects the route to its parent segment'], a: 1, e: '`export const dynamic = \'force-dynamic\'` opts the segment out of prerendering, so Next.js renders it on the server on every request. It caches nothing - that is `force-static` - and it neither disables nor redirects the route. In Next.js 16 this config belongs to the previous caching model and is removed once Cache Components is enabled.', intro: 'This setting decides when the HTML is produced, not whether the route exists or where it points.', tags: ['Next.js', 'Rendering'] },

  // ── Level 9 — Route Handlers ───────────────────────────────────────────
  { q: 'API endpoints in the App Router are defined in which file?', opts: ['page.ts', 'api.ts', 'route.ts', 'handler.ts'], a: 2, e: 'A `route.ts` (or `route.js`) file makes the folder it sits in an endpoint, exporting one function per HTTP method. `page.ts` renders UI for the same segment and cannot live beside `route.ts` at the same path, while `api.ts` and `handler.ts` are not Next.js conventions at all.', intro: 'Endpoints and pages sit in the same folders under `app/`; only the file name separates them.', tags: ['Next.js', 'Route Handlers'] },
  { q: 'A `route.ts` exports functions named after:', opts: ['default', 'handler', 'the HTTP methods (GET, POST, …)', 'api'], a: 2, e: 'A Route Handler exports one named async function per method: `GET`, `POST`, `PUT`, `PATCH`, `DELETE`, `HEAD` and `OPTIONS`. Next.js dispatches on the export name, so a single default export or one function named `handler` - the Pages Router shape - is never called, and a request using a method you did not export gets a 405.', intro: 'Next.js has to route by method without you writing a switch on `request.method`. What could it read instead?', tags: ['Next.js', 'Route Handlers'] },
  { q: '`app/api/users/route.ts` handles requests to:', opts: ['/users', '/api/users', '/route', '/api'], a: 1, e: 'Folders under `app/` become URL segments and `route.ts` handles the folder it sits in, so `app/api/users/route.ts` serves `/api/users`. Here `api` is an ordinary segment, not a prefix Next.js strips, and the file name `route` never appears in the URL.', intro: 'Drop the file name and read the folders that are left as a path.', tags: ['Next.js', 'Route Handlers'] },
  { q: 'A `GET` Route Handler needs to send JSON with an HTTP status and headers. What should it return?', opts: ['A React element for Next.js to serialize', 'A `Response` or `NextResponse` object', 'A plain object with no response conversion', 'The result of `getServerSideProps`'], a: 1, e: 'A Route Handler returns a Web `Response`; `NextResponse` extends it, and both take a status and headers, for example `NextResponse.json(data, { status: 201 })`. Returning a plain object does not work because nothing serializes it into a response, and JSX and `getServerSideProps` belong to rendering and to the Pages Router.', intro: 'Route Handlers speak the Web platform\'s types, not React\'s. What object carries a status and headers?', tags: ['Next.js', 'Route Handlers'] },
  { q: 'Inside a `POST` Route Handler, how do you read the parsed JSON request body?', opts: ['request.body', 'await request.json()', 'req.params', 'useBody()'], a: 1, e: '`request` is a Web `Request`, so `await request.json()` consumes the body stream and parses it. `request.body` is the raw `ReadableStream`, not the parsed object; `req.params` is Express\'s shape for route parameters; and `useBody()` is not real - hooks cannot run in a handler.', intro: 'The `request` here is a Web `Request`, not Express\'s `req`. Ask which interface each option comes from.', tags: ['Next.js', 'Route Handlers'] },
  { q: 'What does `NextResponse.json(data, { status: 201 })` return?', opts: ['A JSX tree that Next.js renders into the response', 'A Response whose body is `data` as JSON, with status 201', 'A redirect response pointing at the current route', 'A thrown error for the nearest error boundary to catch'], a: 1, e: '`NextResponse.json()` serializes the value, sets `content-type: application/json`, and applies the optional init, so this call produces a 201 JSON response for the handler to return. It renders nothing and throws nothing, and a redirect would be `NextResponse.redirect()`.', intro: 'Look at the second argument. Ask what kind of object takes a `ResponseInit` and what `.json()` puts in its body.', tags: ['Next.js', 'Route Handlers'] },
  { q: 'Route Handlers replace which Pages Router feature?', opts: ['getStaticProps', 'the pages/api API routes', 'middleware', '_app'], a: 1, e: '`pages/api/*` held the Pages Router\'s HTTP endpoints, and `route.ts` under `app/` is their App Router equivalent - you do not need both. `getStaticProps` loaded data for a page rather than serving a request, request interception is still its own convention (renamed from `middleware` to `proxy` in Next.js 16), and `_app` was the shared shell that `layout.tsx` replaced.', intro: 'Ask which Pages Router folder held HTTP endpoints rather than pages or data loaders.', tags: ['Next.js', 'Route Handlers'] },
  { q: 'Where does the code in a Route Handler run?', opts: ['In the browser, as part of the client bundle', 'On the server, never in the client bundle', 'At build time only, like a static export', 'On the CDN, with no server involved'], a: 1, e: 'Route Handlers are server code: Next.js never bundles them for the client, so API keys and database access stay on the server. They run per request unless a `GET` opts into caching with `dynamic = \'force-static\'`, and the segment `runtime` defaults to `nodejs`, with `edge` now marked deprecated.', intro: 'Ask where a database password written in that file would end up if the answer were the browser.', tags: ['Next.js', 'Route Handlers'] },

  // ── Level 10 — Server Actions ──────────────────────────────────────────
  { q: 'A Server Action is a function marked with:', opts: ['"use client"', '"use server"', 'async only', 'export action'], a: 1, e: '`"use server"` marks an async function - or, at the top of a file, all of its exports - as server code the client may call over the network. `"use client"` does the opposite and moves a module into the client bundle; being `async` is required but marks nothing on its own, and `export action` is not a directive.', intro: 'Directives are string literals at the top of a file or function. Two of these four are not directives at all.', tags: ['Next.js', 'Server Actions'] },
  { q: 'Server Actions let you:', opts: ['Read data on the server, but never write to it', 'Run server-side mutations from a form or component without a separate API route', 'Render HTML on the client instead of the server', 'Apply scoped styles to a server-rendered component'], a: 1, e: 'A Server Action is server code the client can invoke directly, so a form or an event handler can write to the database without you hand-writing an endpoint for it. Reading is not the limit - mutations are the point - and Next.js still sends the call as a POST request, so the action must check authentication and authorization itself.', intro: 'The name has two halves: \'server\' and \'action\'. Ask what an action does that a plain read does not.', tags: ['Next.js', 'Server Actions'] },
  { q: 'You can invoke a Server Action from:', opts: ['A `useEffect` in a Client Component, and nothing else', 'A `<form action={...}>` or a Client Component event handler', 'Server Components only, since the code runs on the server', 'A `GET` request sent to the route that defines it'], a: 1, e: 'Passing the action to `<form action={...}>` submits to it directly, and a Client Component can also call it from an event handler such as `onClick`. It is not server-only - that is the point of the directive, since the client invokes it over the network - and it is not tied to `useEffect`, while the transport is always POST rather than GET.', intro: 'A Server Action is reached from the browser over the network. Ask which of these could start that request from a page.', tags: ['Next.js', 'Server Actions'] },
  { q: 'A Server Action updates a post, but the post page still shows cached data. Which step tells Next.js that the affected cache is stale?', opts: ['Call `router.refresh()` inside the server-only module', 'Call `revalidatePath()` or `revalidateTag()` for the affected data', 'Call React `setState()` from the Server Action', 'Change the action from `POST` semantics to `GET` semantics'], a: 1, e: 'After a mutation, `revalidatePath(\'/posts/[id]\')` or `revalidateTag(\'posts\')` marks the affected cache entry stale so the next render fetches fresh data. `router.refresh()` is a client hook and cannot run in server-only code, and `setState` never crosses the boundary. In Next.js 16 `revalidateTag` takes a second cacheLife argument and `updateTag` is available when the user must see their own write immediately.', intro: 'The write succeeded; the read is still cached. Ask what has to happen to the cache entry, not to the component.', tags: ['Next.js', 'Server Actions'] },
  { q: 'Why must a Server Action be an `async` function?', opts: ['Because React hooks may only be called from async functions', 'Because the client invokes it over the network and awaits the result', 'Because the server cannot execute synchronous JavaScript', 'Because the App Router compiles every export to a promise'], a: 1, e: 'A Server Action runs on the server, so calling it from the client is a network request, and a network request can only be represented as a promise - hence `async`. It is not a hook rule, the server runs synchronous code perfectly well, and nothing is silently wrapped: you write the function as `async` yourself.', intro: 'The function body never runs on the machine that calls it. What does that make the call?', tags: ['Next.js', 'Server Actions'] },
  { q: 'In a Server Action, what does `revalidateTag("posts", "max")` do?', opts: ['Deletes the records that the "posts" cache entries hold', 'Marks every cache entry tagged "posts" stale, wherever it lives', 'Attaches the tag "posts" to the data fetched in this request', 'Redirects the client to the route that renders the posts list'], a: 1, e: 'Tagging lets one call invalidate data wherever it was cached, so `revalidateTag("posts", "max")` marks every entry labeled "posts" stale regardless of which route rendered it; the path-based alternative, `revalidatePath`, invalidates one route instead. It deletes no records and adds no tag: tags are attached where the data is fetched or cached. Since Next.js 16 the second argument is required - the single-argument form is deprecated and errors in TypeScript - and it sets how long stale content may still be served.', intro: 'A tag is a label many cache entries can share. Ask what happens to all of them at once.', tags: ['Next.js', 'Server Actions'] },
  { q: 'A module begins with `"use server"` and exports three async functions. How does Next.js treat those exports?', opts: ['As Client Component event handlers', 'As server-side functions that can be used as Server Actions', 'As Route Handlers for GET, POST, and PUT', 'As build-time data loaders similar to `getStaticProps`'], a: 1, e: 'A file-level `"use server"` marks every export of that module as server code the client may call, so all three functions can be used as Server Actions. That reach is also the risk: each export becomes reachable by a direct POST, so each needs its own authorization check. They are not Route Handlers, which are named after HTTP methods in a `route.ts`, and `getStaticProps` is a Pages Router data loader with no equivalent here.', intro: 'The directive is at the top of the file, not inside one function. Ask how far its reach extends.', tags: ['Next.js', 'Server Actions'] },
  { q: 'Server Actions are especially useful for:', opts: ['styling', 'form submissions and data mutations', 'routing only', 'client state'], a: 1, e: 'They streamline mutations like form posts without hand-writing API routes.', tags: ['Next.js', 'Server Actions'] },

  // ── Level 11 — Metadata & SEO ──────────────────────────────────────────
  { q: 'To set page metadata in the App Router, you export:', opts: ['a <title> in JSX only', 'a `metadata` object (or generateMetadata)', 'useTitle()', 'a config file'], a: 1, e: 'A page or layout exports a `metadata` object, or a `generateMetadata` function when the values depend on fetched data or route params, and Next.js emits the matching `<head>` tags. React 19 does hoist a `<title>` you render in JSX, so what makes that option wrong is the word \'only\'. There is no `useTitle()` hook, and metadata belongs to a route segment rather than to a project-wide config file.', intro: 'Next.js assembles the head from route segments. One option is close, but the word \'only\' in it is doing real work.', tags: ['Next.js', 'Metadata'] },
  { q: 'What does `export const metadata = { title: "..." }` set?', opts: ['a route', 'the page’s title and meta tags', 'a layout', 'an action'], a: 1, e: 'The metadata object drives <title> and <meta> tags.', tags: ['Next.js', 'Metadata'] },
  { q: 'What is `generateMetadata()` for?', opts: ['Declaring metadata that is fixed and known in advance', 'Building the title and description from fetched data or route params', 'Applying scoped styles to the document head', 'Redirecting a route before its metadata resolves'], a: 1, e: '`generateMetadata` is an async function that receives `params` and can fetch, so a title or description can be derived per route; a plain `metadata` object is a static value and cannot express that. A segment exports one or the other, never both, and neither has anything to do with styling or redirects.', intro: 'One of the two metadata exports is a function you can make `async`. Ask what that buys you.', tags: ['Next.js', 'Metadata'] },
  { q: 'A product page needs a browser title, search description, and social sharing image. Which App Router feature covers all three?', opts: ['Only the page component’s visible `<h1>`', 'The Metadata API, including title, description, and Open Graph fields', 'Only a `favicon.ico` file in `app/`', 'A `headers()` call inside the page component'], a: 1, e: 'The Metadata API declares `title`, `description` and `openGraph.images` from a page or layout, and Next.js emits the head tags all three readers consume. An `<h1>` is page content that no crawler treats as the title, `favicon.ico` sets only the tab icon, and `headers()` reads the incoming request rather than describing the page.', intro: 'The tab, the search result and the chat preview all read the same part of the document, and none of them read the body.', tags: ['Next.js', 'Metadata'] },
  { q: 'You add `app/favicon.ico` to a Next.js project. What happens?', opts: ['It is ignored unless you link it from the root layout yourself', 'It is served as the site favicon and the link tag is generated for you', 'It becomes a route segment that returns the file\'s bytes', 'It fails the build, because `app/` may contain only routes'], a: 1, e: 'Next.js detects `favicon`, `icon` and `apple-icon` files in `app/` and adds the matching `<link>` tags to the head, so no manual link is needed - `favicon.ico` in particular is recognized only at the top level of `app/`. It is not a route segment, and a recognized file convention never breaks the build.', intro: 'Compare it with `page.tsx` and `route.ts`: those names mean something to Next.js. Does this one?', tags: ['Next.js', 'Metadata'] },
  { q: 'You can export `metadata` from:', opts: ['only the root layout', 'a page or a layout', 'only route.ts', 'a hook'], a: 1, e: '`page.js` and `layout.js` can each export `metadata`, and Next.js evaluates them from the root segment downward. The merge is shallow: duplicate keys are replaced by the deeper segment, so a nested `openGraph` set in a layout is overwritten as a whole once the page defines its own. Route Handlers and hooks cannot export metadata, and it is not restricted to the root layout.', intro: 'Both files that make up a rendered route can describe it. Ask what happens when both describe the same field.', tags: ['Next.js', 'Metadata'] },
  { q: 'Open Graph tags primarily help with:', opts: ['Server rendering speed for the first paint', 'How a shared link is previewed on social platforms', 'Which route the browser resolves a URL to', 'How long the CDN keeps the page cached'], a: 1, e: 'Open Graph tags describe the page for platforms that unfurl a shared link - the title, description and image on the preview card. The browser rendering the page ignores them, which is why they affect neither rendering speed, routing nor caching.', intro: 'The tags change nothing a visitor sees on your page. Ask who else reads the document.', tags: ['Next.js', 'Metadata'] },
  { q: 'Why do App Router layouts and pages declare metadata instead of rendering their own `<head>` markup?', opts: ['Because `<head>` may only be written in the `_document` file', 'Because Next.js collects every segment\'s metadata and emits one head', 'Because head tags are not allowed in server-rendered HTML', 'Because a metadata object renders faster than JSX elements'], a: 1, e: 'A route is built from several segments, so Next.js evaluates each one\'s `metadata` from the root down and emits a single head, with deeper segments replacing duplicate keys. Hand-written head markup in a layout could not be reconciled that way. There is no `_document` in the App Router - that was the Pages Router - head tags are perfectly legal in server-rendered HTML, and the reason is reconciliation, not speed.', intro: 'Is `_document` an App Router file? Are `<head>` tags illegal in server HTML? Check each reason before choosing.', tags: ['Next.js', 'Metadata'] },

  // ── Level 12 — Styling ─────────────────────────────────────────────────
  { q: 'CSS Modules use files named:', opts: ['*.css only', '*.module.css', '*.styl', 'styles.js'], a: 1, e: 'A file whose name ends in `.module.css` is compiled as a CSS Module and its class names are rewritten to unique ones, so they cannot collide with another file\'s. A plain `.css` file is global and its selectors apply everywhere; `.styl` is Stylus, which is not built in, and `styles.js` is not a stylesheet at all.', intro: 'The suffix is what the bundler matches on. Ask what the same rules do in a file without it.', tags: ['Next.js', 'Styling'] },
  { q: 'In the App Router, where is an application-wide stylesheet imported?', opts: ['every component', 'the root layout.tsx', 'next.config.js', 'package.json'], a: 1, e: '`app/layout.tsx` is the root layout that wraps every route, so importing `global.css` there loads it once for the whole application. Importing it from each component would repeat the same global rules and make the cascade depend on bundling order, while `next.config.js` and `package.json` are configuration files that do not process CSS imports.', intro: 'Importing the same global sheet from many files does not make it stronger; it makes the cascade depend on bundle order.', tags: ['Next.js', 'Styling'] },
  { q: 'CSS Modules give you:', opts: ['global classes', 'locally scoped class names', 'inline styles', 'no classes'], a: 1, e: 'Class names are hashed/scoped so they don’t collide across files.', tags: ['Next.js', 'Styling'] },
  { q: 'Which preprocessor does Next.js support with no build configuration beyond installing its package?', opts: ['Less, through a built-in `next.config.js` loader', 'Sass, through the `.scss` and `.sass` extensions', 'Stylus, through the `.styl` extension', 'None; every preprocessor needs a custom webpack rule'], a: 1, e: 'Installing `sass` is enough: Next.js then compiles `.scss` and `.sass` files, including `.module.scss` for component-scoped styles, with no config. Less and Stylus have no built-in integration, so \'none at all\' is wrong too.', intro: 'Only one preprocessor is wired into the compiler already; the rest need a loader you write yourself.', tags: ['Next.js', 'Styling'] },
  { q: 'How is Tailwind CSS added to a Next.js App Router project?', opts: ['By setting a `tailwind: true` flag in `next.config.js`', 'By adding Tailwind\'s PostCSS plugin and importing Tailwind from the global stylesheet', 'By loading Tailwind\'s CDN script from the root layout', 'By installing it under `pages/`, since it works only in the Pages Router'], a: 1, e: 'Tailwind runs as a PostCSS plugin: install `tailwindcss` and `@tailwindcss/postcss`, register the plugin in `postcss.config.mjs`, add `@import \'tailwindcss\'` to the global stylesheet, and import that file in the root layout. Next.js has no Tailwind flag of its own, the CDN build is a prototyping tool rather than the documented setup, and Tailwind works in both routers.', intro: 'Tailwind is a build step, not a runtime library. Ask which tool in the pipeline reads your CSS.', tags: ['Next.js', 'Styling'] },
  { q: 'What is `styled-jsx`?', opts: ['A CSS Module loader that Next.js applies to `.module.css` files', 'A scoped CSS-in-JS solution bundled with Next.js, usable in Client Components', 'A PostCSS plugin that compiles Tailwind\'s utility classes', 'A build step that inlines all global CSS into the document head'], a: 1, e: 'styled-jsx ships with Next.js and scopes the CSS you write inside a component to that component. In the App Router it runs only in Client Components - the file needs `"use client"` and a style registry - which is why CSS Modules and Tailwind are the usual choices; it is not a CSS Module loader, a Tailwind plugin, or a global-CSS build step.', intro: 'Three of these describe a build step over a separate `.css` file. Ask what the `jsx` in the name rules out.', tags: ['Next.js', 'Styling'] },
  { q: 'After `import styles from "./x.module.css"`, you apply a class with:', opts: ['className="foo"', 'className={styles.foo}', 'style={styles}', 'css={foo}'], a: 1, e: 'The import gives you an object that maps each class you wrote to the unique name the compiler generated, so `className={styles.foo}` resolves to that generated name. Writing `className="foo"` compiles fine and silently matches nothing, because no element ever carries the literal name; `style` takes a CSS property object, and `css={...}` belongs to other libraries.', intro: 'The name you typed in the stylesheet is not the name in the DOM. Which value knows the real one?', tags: ['Next.js', 'Styling'] },
  { q: 'What happens to the class names written in a `.module.css` file?', opts: ['They reach the DOM exactly as written in the file', 'They are rewritten at build time to names unique to that file', 'They are removed and replaced by inline style attributes', 'They are registered globally so any component can use them'], a: 1, e: 'The compiler rewrites each class to a name unique to its file, so two stylesheets can both define `.title` without either overriding the other, and the imported object maps your name to the generated one. The names therefore do not survive as written, no inline styles are involved, and nothing becomes global - that is what plain `.css` files are for.', intro: 'Open devtools on a component styled by a CSS Module and read its `class` attribute.', tags: ['Next.js', 'Styling'] },

  // ── Level 13 — Images & Fonts ──────────────────────────────────────────
  { q: 'Which component does Next.js provide for optimized images?', opts: ['`<img>`, which Next.js optimizes automatically', '`<Image>`, imported from `next/image`', '`<Picture>`, imported from `next/picture`', '`<NextImg>`, available globally without an import'], a: 1, e: '`next/image` exports `<Image>`, which serves resized images in modern formats and lazy-loads them. A plain `<img>` is passed straight through, so none of that applies to it - that is the point of having a component at all. `<Picture>` and `<NextImg>` do not exist in Next.js.', intro: 'The framework cannot change a tag the browser already owns. What does it hand you instead?', tags: ['Next.js', 'Images'] },
  { q: 'What does `<Image>` do that a plain `<img>` does not?', opts: ['Applies a default border and rounded corners', 'Serves a resized, modern-format file and reserves its space while it loads', 'Uploads the file to a CDN during `next build`', 'Prevents the image from loading at all when JavaScript is disabled'], a: 1, e: '`next/image` requests an image resized and re-encoded for the device that asked for it, lazy-loads what is off screen, and uses the declared dimensions to hold the space so the page does not jump when the file arrives. A plain `<img>` does none of that. It adds no styling of its own, uploads nothing during the build, and it renders an ordinary `<img>` element, so the picture still appears with JavaScript disabled.', intro: 'Compare the network request and the layout, not the appearance.', tags: ['Next.js', 'Images'] },
  { q: 'A local `<Image>` has a `src` and `alt` value but no layout dimensions. What should you normally add to prevent layout shift?', opts: ['Only a `className` with `display: block`', '`width` and `height`, or the `fill` prop with a sized parent', 'Only `loading="eager"` so the image arrives sooner', 'A manual `<link rel="preload">` for every image'], a: 1, e: 'Width and height give Next.js the aspect ratio, so the space is held from the first paint and the content below does not jump; `fill` is the alternative when a positioned, sized parent decides the box. `loading="eager"` only starts the request sooner - the image still has no known size until it arrives - and a hand-written preload has the same problem while adding markup for every image.', intro: 'The browser has to reserve the box before the bytes arrive. Ask what tells it the shape.', tags: ['Next.js', 'Images'] },
  { q: 'What does `next/font` let you do?', opts: ['Load font files from a third-party CDN on every page view', 'Self-host and preload font files, with a metric-matched fallback so text does not shift', 'Delay font loading until after the page becomes interactive', 'Replace web fonts with the operating system\'s default font'], a: 1, e: '`next/font` copies the font files into your own build output and preloads them, so no request goes to a third party at runtime. It also generates a fallback font whose metrics are adjusted to match the real one, so the text does not reflow when the web font loads. Nothing is delayed or replaced by a system font.', intro: 'Fonts arrive after the first paint. Ask what the page shows in the meantime, and where the file came from.', tags: ['Next.js', 'Fonts'] },
  { q: 'What does `next/font/google` do with the font you import?', opts: ['Requests it from Google\'s servers on every page view', 'Downloads it at build time and serves it from your own domain', 'Adds a `<link>` to fonts.googleapis.com in the document head', 'Nothing; Google Fonts are not supported by `next/font`'], a: 1, e: 'The CSS and font files are downloaded during `next build` and served as static assets from your own deployment, so the visitor\'s browser sends no request to Google - which removes both a third-party round trip and the privacy exposure that comes with it. That is also why neither a runtime fetch nor a `<link>` to fonts.googleapis.com appears in the output.', intro: 'Ask what the visitor\'s browser requests at runtime, and from whose server.', tags: ['Next.js', 'Fonts'] },
  { q: 'How does `<Image>` load images by default?', opts: ['Every image is requested as soon as the HTML parses', 'Off-screen images are deferred until the viewport approaches them', 'No image loads until the page becomes interactive', 'The page waits for all images before showing any of them'], a: 1, e: '`<Image>` renders `loading="lazy"`, so an image below the fold is requested only as the viewport nears it - which is also why the hero image needs an explicit opt-out. Nothing waits for interactivity, and images never block the page from rendering.', intro: 'Most images on a long page are never scrolled to. Ask what a sensible default does with those.', tags: ['Next.js', 'Images'] },
  { q: 'A hero image is the page\'s LCP element. Which `<Image>` prop preloads it instead of leaving it to lazy loading?', opts: ['Raise `quality` so the browser treats the file as important', 'Set the `preload` prop (`priority` in Next.js 15 and earlier)', 'Wrap the image in `<Suspense>` with a fallback', 'Give it a larger `width` than the other images on the page'], a: 1, e: 'Marking the image for preloading inserts a `<link rel="preload">` in the head, so the browser starts the request before it reaches the `<img>` in the body, which is what an LCP hero needs. The prop is `preload` in Next.js 16; `priority` did the same job in earlier versions and is now deprecated. Quality changes the bytes, width changes the layout, and a Suspense boundary changes where rendering pauses; none of them change fetch order.', intro: 'The default defers off-screen images. The largest one is not off screen, so it needs the opposite instruction.', tags: ['Next.js', 'Images'] },
  { q: '`<Image>` rejects URLs from `cdn.example.com`, while local images work. Which configuration is missing?', opts: ['A rewrite that sends every image request through an API route', 'An `images.remotePatterns` entry that allows the CDN URL pattern', 'A base64 conversion step in every component that uses the image', 'A public environment variable containing the full image bytes'], a: 1, e: 'The optimizer runs on your server, so an unrestricted `src` would let anyone make it fetch and re-serve arbitrary URLs; `images.remotePatterns` is the allowlist that prevents this, matched on protocol, hostname and path. Adding the CDN\'s pattern is the fix; the older `images.domains` list has been deprecated since Next.js 14 because it cannot restrict protocol, port or path. Rewrites, base64 inlining and environment variables all work around the optimizer instead of configuring it.', intro: 'The optimizer fetches the URL you give it. Ask why it refuses to fetch just any host.', tags: ['Next.js', 'Images'] },

  // ── Level 14 — Loading & Errors ────────────────────────────────────────
  { q: 'What does `loading.tsx` show?', opts: ['The page shown when no route matches the URL', 'The fallback shown while that segment\'s content is still loading', 'The UI rendered when the segment throws during rendering', 'The shared shell that wraps every page in the segment'], a: 1, e: 'Adding `loading.tsx` makes Next.js wrap that segment in a Suspense boundary automatically, so the file\'s UI is shown immediately while the segment\'s own content streams in. A missing route is `not-found.tsx`, a thrown error is `error.tsx`, and the shared shell is `layout.tsx`.', intro: 'Each wrong option is the job of a different file in the same folder. Work out which file owns each.', tags: ['Next.js', 'Loading'] },
  { q: 'What must the top of an `error.tsx` file contain, and why?', opts: ['Nothing special; it renders on the server like any other segment file', '`"use client"`, because the boundary has to run and re-render in the browser', '`"use server"`, because the error is captured during server rendering', 'An `export const dynamic` config, because errors cannot be prerendered'], a: 1, e: 'An error boundary catches failures thrown while rendering the segments it wraps, on the server or in the browser, and then shows interactive recovery UI, so it must run in the browser: `error.tsx` starts with `"use client"`. A Server Component cannot hold the state or the click handler this needs, and no segment config changes that. It is also why `metadata` cannot be exported from `global-error`.', intro: 'The Try again button has to work after the page is delivered. Which environment is that?', tags: ['Next.js', 'Errors'] },
  { q: 'A route error UI needs to display the failure and offer a “Try again” button. Which props does `error.tsx` receive for those jobs?', opts: ['Only `children` and `fallback`', 'An `error` object and a function that re-renders the segment', 'Only route `params` and `searchParams`', 'A Node.js request and response pair'], a: 1, e: '`error.tsx` receives the captured `Error` - carrying a `digest` you can match against the server log, since production hides the original message - and a function for the Try again button. In Next.js 16 that function is `retry`, which re-fetches and re-renders the boundary\'s children; `reset` still exists and re-renders them without re-fetching. `children`/`fallback` belong to a Suspense boundary, `params` to a page, and a request/response pair to a Route Handler.', intro: 'An error boundary is a React component, not a request handler and not a Suspense boundary.', tags: ['Next.js', 'Errors'] },
  { q: 'What does calling `reset()` from `error.tsx` do?', opts: ['Reloads the document, the way `location.reload()` would', 'Re-renders the boundary\'s children in place, without a page load', 'Navigates the user to the nearest parent route', 'Clears the client cache for every route in the app'], a: 1, e: '`reset()` clears the error state and renders the boundary\'s children again in place, so the URL and any client state outside that segment survive - a document reload would discard both. It does not navigate anywhere. In Next.js 16 the preferred prop is `retry()`, which re-fetches the segment\'s data before re-rendering it.', intro: 'Compare it with hitting the browser\'s reload button. Ask what that would throw away that you would rather keep.', tags: ['Next.js', 'Errors'] },
  { q: 'What does streaming with Suspense change about how a server-rendered page is delivered?', opts: ['The whole response is held until every query has finished', 'Ready parts are sent first and slower parts follow as they resolve', 'Rendering moves to the browser so the server sends only a shell', 'The rendered HTML is cached and reused for every later request'], a: 1, e: 'Streaming lets the server flush the parts of the page that are ready and send each remaining part when its data resolves, so the slowest query no longer sets the time to first paint. It is still server rendering - the browser is not taking over - and it caches nothing.', intro: 'One slow query used to decide when the whole page appeared. Ask what a boundary lets the server send in the meantime.', tags: ['Next.js', 'Loading'] },
  { q: 'What does wrapping a slow server component in `<Suspense fallback={<Skeleton />}>` achieve?', opts: ['The rest of the page waits until that component\'s data resolves', 'The rest of the page is sent first, with the skeleton in that component\'s place', 'The component moves to the client and fetches its own data there', 'The component\'s rendered output is cached until the next deployment'], a: 1, e: 'A Suspense boundary lets the server send everything outside it immediately and stream the real content into the hole when its data resolves, with the fallback holding the space meanwhile - so one slow query no longer delays the whole page. Nothing moves to the client, and the boundary caches nothing.', intro: 'The boundary marks one hole in the page. Ask what the server may do with everything around it.', tags: ['Next.js', 'Loading'] },
  { q: 'Which failures does `app/global-error.tsx` catch?', opts: ['Errors thrown inside any one route segment', 'Errors thrown by the root layout itself', 'Requests for URLs that match no route', 'Segments that are still waiting for their data'], a: 1, e: '`error.tsx` wraps the segments beneath it but not the layout above it, so a failure in the root layout has no boundary - `global-error.tsx` is that boundary. It replaces the root layout while active, which is why it has to render its own `<html>` and `<body>` and pull in its own styles. Unmatched URLs go to `not-found.tsx` and pending data to `loading.tsx`.', intro: 'An `error.tsx` wraps what is below it. Ask what is left above the outermost one.', tags: ['Next.js', 'Errors'] },
  { q: 'What causes `not-found.tsx` to render?', opts: ['An exception thrown anywhere in the segment', 'A `notFound()` call, or an unmatched URL at the root', 'A redirect issued by `redirect()` or middleware', 'A segment whose data has not resolved yet'], a: 1, e: 'Calling `notFound()` in a segment renders that segment\'s `not-found.tsx`, and the root `app/not-found.tsx` additionally answers any URL that matches no route - a nested one never does. Uncaught exceptions go to `error.tsx`, redirects are handled by `redirect()`, and unresolved data shows `loading.tsx`.', intro: 'Two different things end up here: one your code decides, one the router decides.', tags: ['Next.js', 'Errors'] },

  // ── Level 15 — Middleware & Config ─────────────────────────────────────
  { q: 'When does middleware run relative to a request?', opts: ['After the route has rendered, so it can edit the HTML', 'Before the request reaches a route, so it can redirect or rewrite', 'Only during `next build`, while routes are prerendered', 'In the browser, before the request is sent'], a: 1, e: 'Middleware runs on the server in front of your routes, so it can rewrite, redirect, set headers or respond before any route code executes; once a route has rendered that chance is gone. It is not a build step and not browser code. Next.js 16 renames the convention to Proxy for exactly this reason - it sits at the network boundary - and recommends using it only when nothing else fits.', intro: 'Its job is to answer or reroute a request. Ask when a decision like that is still available.', tags: ['Next.js', 'Middleware'] },
  { q: 'Where does Next.js look for the file that intercepts requests before they reach a route?', opts: ['Inside `app/`, beside the routes it should guard', 'At the project root or in `src/`, as `proxy.ts` (formerly `middleware.ts`)', 'In `next.config.js`, under a `proxy` key', 'In any `route.ts`, as an export named `proxy`'], a: 1, e: 'The file sits beside `app/` - at the project root, or in `src/` if the project uses one - so it can match any request before a route runs. Next.js 16 renamed it from `middleware.ts` to `proxy.ts` and the exported function from `middleware` to `proxy`, with a codemod for the rename. It is not a `next.config.js` key and not an export from a route file.', intro: 'It has to see requests for every route, so it cannot live inside any single one of them.', tags: ['Next.js', 'Middleware'] },
  { q: 'Which jobs is middleware normally used for?', opts: ['Rendering the page\'s HTML before the route runs', 'Redirects, rewrites, headers and coarse auth gating', 'Fetching and caching the data a page will need', 'Bundling the client JavaScript for the matched route'], a: 1, e: 'Middleware inspects the incoming request, so it can redirect, rewrite the URL, or set headers before any route runs, which is why coarse auth gating lives there. Rendering, data fetching and bundling all happen after it and belong to the route itself. Next.js 16 renames the convention to Proxy and recommends reaching for it only when no other API fits.', intro: 'It sees the request but never the rendered page. Ask which of these need only the request.', tags: ['Next.js', 'Middleware'] },
  { q: 'Which file holds a Next.js project\'s configuration?', opts: ['`config.json` in the project root', '`next.config.js`, or `.mjs` / `.ts`', 'A `next` key inside `package.json`', '`.nextrc` in the project root'], a: 1, e: 'Next.js reads `next.config.js` (or `next.config.mjs` / `next.config.ts`) from the project root and expects it to export a config object - a module rather than data, so plugins can wrap it and values can be computed. `package.json` describes the package for the package manager, and neither `config.json` nor `.nextrc` is a Next.js convention.', intro: 'Ask which file the framework itself reads at startup, not one the package manager reads.', tags: ['Next.js', 'Config'] },
  { q: 'Env vars exposed to the browser must be prefixed with:', opts: ['PUBLIC_', 'NEXT_PUBLIC_', 'REACT_APP_', 'ENV_'], a: 1, e: 'Only names beginning with `NEXT_PUBLIC_` are inlined into the JavaScript sent to the browser; every other variable stays in the server environment. `REACT_APP_` is Create React App\'s prefix and `PUBLIC_` belongs to other tools, so a variable with the wrong prefix is simply `undefined` in client code - which is the symptom that sends people looking for this rule.', intro: 'Two of these prefixes come from other tools and one is made up. The right one also says, in the name, what it does.', tags: ['Next.js', 'Config'] },
  { q: 'What happens to a `NEXT_PUBLIC_*` environment variable?', opts: ['It stays on the server and never reaches the browser', 'It is inlined into the client bundle during `next build`', 'It is encrypted before it is sent to the browser', 'It is ignored unless it is also listed in `next.config.js`'], a: 1, e: 'The value is substituted into the JavaScript sent to the browser during `next build`, so anyone can read it in the bundle - never put a secret behind this prefix. Because it is baked in at build time, changing the variable afterwards has no effect until you rebuild, which is what catches teams promoting one image between environments. Nothing is encrypted and no config entry is involved.', intro: 'Ask who can read the value once the page is served, and when that value was decided.', tags: ['Next.js', 'Config'] },
  { q: 'In Next.js 16, which runtime does the request-interception file (`proxy.ts`) run on?', opts: ['The Edge runtime, as `middleware.ts` did by default', 'The Node.js runtime, and it cannot be configured', 'Whichever runtime `export const runtime` names in the file', 'The browser, before the request leaves the client'], a: 1, e: '`proxy.ts` runs on the Node.js runtime; the `runtime` segment config is not available there and setting it throws. `middleware.ts` did default to the Edge runtime, with Node.js becoming a stable opt-in in 15.5, which is why older material says Edge - keep `middleware` if you still need the Edge runtime. It never runs in the browser: it sits in front of the app, not inside it.', intro: 'The rename came with a change of environment. Recall which of the two server runtimes the current release settled on.', tags: ['Next.js', 'Middleware'] },
  { q: 'A common, first-class host for deploying Next.js is:', opts: ['only AWS', 'Vercel (among others)', 'GitHub Pages only', 'a database'], a: 1, e: 'Vercel (the maker of Next.js) is a common deploy target, though many work.', tags: ['Next.js', 'Config'] },
];
